import { entry, MAX_ENTRIES } from './engine.js';
export const yieldToUI=()=>new Promise(resolve=>setTimeout(resolve,0));
export async function makeNumberEntries(start,step,count,onProgress=()=>{}){if(!Number.isInteger(count)||count<1||count>MAX_ENTRIES)throw Error('Generate between 1 and 1,000,000 numbers.');const entries=new Array(count);for(let i=0;i<count;i++){entries[i]=entry(String(Number((start+i*step).toPrecision(12))));if((i+1)%10000===0){onProgress((i+1)/count);await yieldToUI();}}return entries;}
export function captureWorkspace(wheels,activeId){return {activeId,wheels:wheels.map(w=>({...w,entries:w.entries.map(e=>({...e})),appearanceSettings:{...w.appearanceSettings,palette:[...w.appearanceSettings.palette]},spinSettings:{...w.spinSettings},winnerSettings:{...w.winnerSettings},soundSettings:{...w.soundSettings}}))};}
export function trimUndo(stack){let total=stack.reduce((sum,s)=>sum+s.wheels.reduce((n,w)=>n+w.entries.length,0),0);while(stack.length>1&&(stack.length>50||total>2_000_000)){const removed=stack.shift();total-=removed.wheels.reduce((n,w)=>n+w.entries.length,0);}return stack;}
export async function reconcileEntries(lines,previous,onProgress=()=>{}){if(lines.length>MAX_ENTRIES)throw Error('The maximum is 1,000,000 entries.');const pools=new Map();for(let i=0;i<previous.length;i++){const e=previous[i];let pool=pools.get(e.text);if(!pool){pool={entries:[],cursor:0};pools.set(e.text,pool);}pool.entries.push(e);if(i&&i%20000===0)await yieldToUI();}const result=new Array(lines.length);for(let i=0;i<lines.length;i++){const text=lines[i];if(text.length>1000)throw Error('Each entry can contain up to 1,000 characters.');const pool=pools.get(text);result[i]=pool&&pool.cursor<pool.entries.length?pool.entries[pool.cursor++]:entry(text);if(i&&i%10000===0){onProgress(i/lines.length);await yieldToUI();}}return result;}
